/* Role-based learning guides — Strategy & Planning + Paid Search.
 * Each chapter is tied to its role workflow; examples are SIMULATED.
 */
var ROLE_GUIDES = ROLE_GUIDES || {};
ROLE_GUIDES.connection = {
 scope:"Connection Planner menerjemahkan business challenge menjadi alasan untuk berkomunikasi, audience insight, peran touchpoint, arsitektur pesan, dan learning agenda. Output utamanya adalah strategi komunikasi yang menjelaskan siapa yang perlu berubah, perubahan apa yang diharapkan, mengapa pesan relevan, dan di mana pengalaman itu terjadi. Role ini bukan sekadar media buyer atau pembuat content calendar.",
 workflow:[
  "<b>Frame the challenge.</b> Pisahkan business problem, communication problem, behavior/perception shift, audience, constraint, dan success criteria.",
  "<b>Find the human truth.</b> Gabungkan consumer evidence, context, cultural signal, category behavior, dan tension; pisahkan fakta dari interpretasi.",
  "<b>Design the connection.</b> Turunkan proposition, message hierarchy, journey moments, channel roles, touchpoint sequence, dan experience handoff.",
  "<b>Measure and learn.</b> Tetapkan indikator komunikasi, exposure quality, brand/behavior outcomes, learning questions, dan batas atribusi.",
  "<b>Make it executable.</b> Susun deck, brief, owner, timing, dependencies, assumptions, dan risk agar creative, media, activation, serta client team bisa bekerja."
 ],
 qa:[
  "Insight komunikasi harus menjelaskan tension atau barrier yang didukung bukti, bukan kalimat demografis atau slogan. Tunjukkan sumber, konteks, alternatif interpretasi, dan implikasi terhadap pesan.",
  "Channel dipilih berdasarkan peran pada journey dan perubahan yang ingin diciptakan. Jelaskan audience fit, timing, format, attention/credibility, handoff, overlap, serta peran channel lain; jangan memilih hanya karena reach besar.",
  "Ukur perubahan yang sesuai tujuan komunikasi: exposure yang layak, recall/awareness, consideration, search/engagement berkualitas, behavior, atau sales bila jalur datanya tersedia. Cantumkan baseline, window, metode, dan limitation."
 ],
 glossary:[
  ["Communication challenge","Masalah komunikasi yang harus dipecahkan untuk mendukung business outcome."],
  ["Human tension","Konflik kebutuhan, motivasi, atau hambatan yang menjelaskan perilaku audience."],
  ["Cultural insight","Pola konteks sosial/budaya yang relevan dan dapat mengubah cara brand berkomunikasi."],
  ["Proposition","Janji nilai atau gagasan utama yang ingin disampaikan brand."],
  ["Reason to believe","Bukti yang membuat proposition masuk akal."],
  ["Touchpoint","Momen atau interaksi ketika audience dapat bertemu brand/pesan."],
  ["Connection architecture","Rancangan hubungan pesan, channel, timing, dan journey."],
  ["Message hierarchy","Urutan pesan utama, pendukung, proof, dan CTA."],
  ["Learning agenda","Pertanyaan yang akan diuji untuk memperbaiki strategi berikutnya."],
  ["Experience handoff","Penyerahan strategi ke creative, media, activation, dan experience team."]
 ],
 chapters:[
  {
   concept:"Sebuah brief sering memuat gejala seperti awareness rendah, penjualan turun, atau campaign dianggap kurang engaging. Connection Planner harus menguji apakah masalahnya pengetahuan, persepsi, relevansi, kepercayaan, akses, atau pengalaman. Communication objective tidak boleh otomatis disamakan dengan media objective; definisikan perubahan audience dan bukti keberhasilannya terlebih dahulu.",
   example:"SIMULASI — minuman baru punya awareness 35% di target, tetapi trial rendah. Interview menunjukkan audience sudah tahu produknya namun belum paham alasan memilihnya dibanding alternatif. Problem komunikasi mungkin bukan reach, melainkan differentiation dan reason to believe. Validasi dengan research sebelum mengusulkan campaign.",
   actions:["Tulis ulang brief dalam format business symptom → communication problem → audience shift → evidence gap.","Buat success criteria yang bisa diamati; pisahkan outcome bisnis, communication KPI, dan diagnostic metric.","Buat daftar pertanyaan klarifikasi ke client: baseline, target, category context, mandatory claim, budget, timing, decision owner."],
   practice:"Buat brief restatement dua halaman untuk satu brand latihan. Sertakan business goal, communication challenge, audience, desired shift, barrier, evidence yang tersedia, evidence yang belum ada, scope, constraint, success criteria, dan tiga pertanyaan klarifikasi. Jangan mengarang baseline.",
   qaFocus:["membedakan business symptom dengan communication problem","menulis success criteria yang mengukur perubahan audience","memutuskan bukti apa yang perlu diminta sebelum menyusun strategi"],
   terms:[["Business problem","Masalah komersial atau organisasi yang mendasari brief."],["Communication objective","Perubahan pengetahuan, persepsi, sikap, atau tindakan audience yang dituju."],["Success criteria","Kondisi terukur yang menunjukkan apakah strategi berhasil."]]
  },
  {
   concept:"Audience research menggabungkan sumber primer dan sekunder untuk memahami kebutuhan, keputusan, hambatan, serta konteks konsumsi media. Segmentasi yang baik bukan hanya usia atau lokasi; segmentasi harus memprediksi kebutuhan komunikasi yang berbeda. Gunakan interview, survey, sales/CRM, search behavior, review, social conversation, dan data kategori dengan mempertimbangkan representativeness dan bias.",
   example:"SIMULASI — dua segmen pembeli kopi siap minum sama-sama berusia 20–30 tahun. Segmen A butuh convenience saat commuting; segmen B mencari rasa baru untuk social occasions. Mereka membutuhkan message, proof, occasion, dan channel trigger yang berbeda.",
   actions:["Tentukan research question sebelum memilih metode; bedakan exploratory research dan validation.","Gabungkan evidence primer/sekunder, catat sample, periode, geografi, sumber, dan limitation.","Susun segment profile berbasis need, occasion, motivation, barrier, decision criteria, dan media behavior."],
   practice:"Buat audience deck untuk dua segmen: profile, job-to-be-done, occasion, need, tension, barrier, alternative, decision criteria, media context, evidence, confidence level, dan communication implication. Tandai setiap insight sebagai observed, interpreted, atau hypothesis.",
   qaFocus:["membuat segmen berdasarkan needs dan behavior, bukan demographic label saja","menilai bias dan keterbatasan sumber riset","menghubungkan insight segmen ke keputusan komunikasi"],
   terms:[["Primary research","Data yang dikumpulkan langsung untuk menjawab research question."],["Secondary research","Data yang sudah tersedia dari sumber lain, misalnya CRM, laporan, search, atau review."],["Job-to-be-done","Tugas/kebutuhan yang ingin diselesaikan audience dalam konteks tertentu."]]
  },
  {
   concept:"Cultural insight bukan sekadar tren viral. Insight harus menjelaskan mengapa sebuah perilaku muncul, ketegangan apa yang dirasakan audience, mengapa hal itu relevan sekarang, dan apa implikasinya bagi brand. Validasi sinyal tren dengan konteks, durasi, skala, kategori, dan bukti; jangan menggeneralisasi percakapan niche sebagai perilaku massal.",
   example:"SIMULASI — tren 'slow living' ramai di platform video, tetapi tidak semua audiens menginginkan produk premium. Analisis komentar dan interview menunjukkan sebagian audience mencari cara menghemat energi dan waktu, bukan aspirational lifestyle. Brand perlu menghindari penafsiran yang dangkal.",
   actions:["Kumpulkan sinyal dari search, social listening, comments, community, review, dan desk research.","Pisahkan trend signal, observation, interpretation, dan human tension.","Nilai relevance, evidence, cultural sensitivity, longevity, brand permission, dan potential misinterpretation."],
   practice:"Susun tiga kandidat insight. Untuk masing-masing isi signal, evidence, audience tension, cultural context, counter-evidence, brand relevance, implication, dan risiko salah tafsir. Pilih satu insight dan tulis platform idea satu paragraf.",
   qaFocus:["membedakan viral trend dengan insight yang punya explanatory power","menguji apakah cultural signal cukup relevan dengan audience dan brand","mengubah tension menjadi communication opportunity tanpa stereotyping"],
   terms:[["Cultural signal","Sinyal perubahan percakapan atau praktik sosial yang perlu diuji konteksnya."],["Insight","Penjelasan bermakna tentang motivasi atau tension yang didukung evidence."],["Cultural sensitivity","Pertimbangan terhadap konteks, dampak, dan potensi salah representasi budaya."]]
  },
  {
   concept:"Positioning menetapkan ruang pembeda brand; communication strategy mengubahnya menjadi gagasan yang dapat dipahami audience. Proposition harus relevan, berbeda, kredibel, dan dapat dibuktikan. Susun message hierarchy dari proposition ke key message, supporting message, proof, objection handling, dan CTA. Pastikan strategi tidak membuat klaim di luar product truth atau substantiation yang tersedia.",
   example:"SIMULASI — dua layanan pengiriman sama-sama menjanjikan cepat. Satu punya coverage luas, satu punya kepastian slot waktu. Jika target audience mengutamakan predictability, proposition yang lebih spesifik mungkin lebih kuat daripada sekadar mengulang 'tercepat'.",
   actions:["Tentukan category frame, target audience, alternative, point of difference, benefit, dan proof.","Susun proposition serta message hierarchy untuk awareness, consideration, dan action.","Uji clarity, relevance, distinctiveness, credibility, objection, serta claim substantiation."],
   practice:"Buat communication strategy one-pager: positioning context, target, tension, proposition, proof, message hierarchy, objection handling, CTA, mandatories, dan claims to avoid. Sertakan satu alternatif proposition dan alasan penolakannya.",
   qaFocus:["membedakan positioning dari campaign tagline","memastikan proposition didukung proof dan klaim yang dapat disubstansiasi","membuat message hierarchy konsisten lintas journey"],
   terms:[["Positioning","Ruang pembeda yang ingin ditempati brand relatif terhadap alternatif."],["Key message","Pesan utama yang harus dipahami audience."],["Claim substantiation","Bukti yang dibutuhkan untuk mendukung klaim brand."]]
  },
  {
   concept:"Customer journey memetakan tindakan dan keputusan lintas waktu, bukan sekadar funnel linear. Touchpoint audit melihat apa yang sudah dimiliki brand, apa yang hilang, dan di mana pengaruh terjadi. Momen prioritas dipilih berdasarkan audience need, barrier, opportunity, dan feasibility; sebuah touchpoint dapat berperan sebagai reassurance, discovery, proof, transaction, atau service.",
   example:"SIMULASI — calon pembeli mencari review di marketplace, bertanya pada komunitas, melihat video creator, lalu mengunjungi toko fisik. Jika strategi hanya menargetkan iklan awareness, brand melewatkan momen validasi sosial dan ketersediaan produk.",
   actions:["Petakan stages, actions, questions, emotion, influence, barrier, dan decision moment.","Inventarisasi paid, owned, earned, shared, commerce, service, dan offline touchpoint.","Prioritaskan momen berdasarkan impact, audience need, gap, cost, controllability, dan measurement."],
   practice:"Buat journey dan touchpoint map end-to-end. Tandai momen paling menentukan, current experience, friction, message need, channel opportunity, owner, KPI, dan evidence. Pilih tiga touchpoint prioritas beserta alasan.",
   qaFocus:["mengidentifikasi momen keputusan di luar urutan funnel linear","membedakan peran touchpoint dengan sekadar daftar platform","memprioritaskan touchpoint berdasarkan audience need dan impact"],
   terms:[["Journey stage","Tahap tindakan atau keputusan dalam pengalaman audience."],["Moment of truth","Momen yang berpengaruh besar pada persepsi atau keputusan."],["Touchpoint audit","Pemeriksaan pengalaman brand pada titik kontak yang ada."]]
  },
  {
   concept:"Paid, owned, earned, dan shared adalah kerangka kepemilikan/distribusi; peran channel harus ditentukan dari tugasnya pada journey. Paid bisa menciptakan atau menangkap demand, owned memberi informasi dan service, earned memberi legitimasi, shared memfasilitasi partisipasi. Jangan menganggap setiap channel bisa saling menggantikan atau menggunakan KPI yang sama.",
   example:"SIMULASI — brand launch: video paid social membangun discovery, search menangkap intent, website menjelaskan proof, creator review memberi third-party perspective, dan komunitas menjadi ruang tanya jawab. Tiap channel punya fungsi dan horizon pengukuran berbeda.",
   actions:["Definisikan communication task pada tiap journey stage.","Nilai audience fit, role, format, timing, credibility, reach, controllability, dan dependency.","Susun channel-role matrix, overlap, sequencing, dan guardrail agar tidak terjadi duplikasi."],
   practice:"Buat channel-role matrix untuk satu campaign: paid/owned/earned/shared, audience task, message, format, timing, KPI, source, owner, dependency, dan limitation. Jelaskan mengapa minimal dua channel tidak boleh dinilai dengan satu KPI yang sama.",
   qaFocus:["menetapkan channel berdasarkan tugas komunikasi","membedakan paid/owned/earned/shared tanpa menganggapnya eksklusif","menyusun KPI sesuai role dan horizon channel"],
   terms:[["Paid media","Distribusi melalui inventory berbayar."],["Earned media","Eksposur atau pembicaraan yang diperoleh dari pihak lain."],["Shared media","Distribusi atau percakapan yang melibatkan partisipasi audience."]]
  },
  {
   concept:"Communication architecture menyatukan proposition, message, proof, CTA, channel role, dan journey stage. Framework yang baik memiliki satu ide inti tetapi mengizinkan adaptasi platform. Jangan melakukan copy-paste pesan yang sama ke semua placement; adaptasikan panjang, format, context, proof, dan action tanpa merusak brand meaning.",
   example:"SIMULASI — proposition yang sama diterjemahkan menjadi 6-second video hook, carousel explainer, search ad headline, landing-page proof block, creator talking point, dan CRM reminder. Semua punya peran berbeda tetapi tetap konsisten.",
   actions:["Tentukan single-minded proposition dan supporting pillars.","Susun message matrix per stage, audience, channel, format, proof, dan CTA.","Definisikan invariants (brand truth) serta variables (tone, length, format, interaction)."],
   practice:"Buat communication architecture dan message matrix minimal empat channel. Setiap baris memuat journey stage, message job, proof, format, CTA, tone, adaptation rule, dan measurement.",
   qaFocus:["membuat konsistensi ide tanpa copy-paste format","menghubungkan message ke audience stage dan CTA","menjaga proof dan brand truth ketika pesan diadaptasi"],
   terms:[["Communication architecture","Struktur pesan, channel, timing, dan audience stage."],["Message matrix","Tabel pesan menurut audience, stage, channel, dan CTA."],["Platform-native","Format dan perilaku komunikasi yang sesuai karakter platform."]]
  },
  {
   concept:"Creative brief adalah kontrak kerja antara strategy dan creative team. Brief harus menjelaskan problem, audience, insight, proposition, mandatories, deliverables, channel context, timing, dan criteria for approval. Orchestration plan menerangkan urutan pengalaman dan handoff, bukan hanya jadwal posting. Handoff harus menjaga intention strategy sambil memberi ruang ide kreatif.",
   example:"SIMULASI — creative team menerima brief 'buat konten viral'. Hasilnya tidak konsisten karena tidak ada target audience, message job, mandatories, placement, atau approval owner. Brief diperbaiki menjadi satu halaman dengan objective, insight, proposition, audience action, format, and success criteria.",
   actions:["Tuliskan audience, tension, single-minded proposition, proof, mandatories, dan do/don't.","Susun deliverable matrix, production timing, approval gates, owner, dependency, dan asset specs.","Buat orchestration timeline dan handoff criteria ke creative, media, activation, dan CX."],
   practice:"Tulis creative brief lengkap untuk satu campaign dan buat orchestration plan. Sertakan RACI ringkas, timeline, approval rounds, asset matrix, version control, escalation, dan sign-off checklist.",
   qaFocus:["membuat brief yang bisa dikerjakan tanpa kehilangan strategi","menentukan ownership dan approval agar workflow tidak macet","menjaga continuity dari creative delivery ke channel experience"],
   terms:[["Creative brief","Dokumen arahan kerja yang menghubungkan strategi dengan output kreatif."],["Orchestration","Pengaturan pesan/touchpoint secara berurutan dan saling melengkapi."],["RACI","Matriks responsible, accountable, consulted, informed."]]
  },
  {
   concept:"Communication effectiveness mengukur apakah komunikasi mencapai audience yang tepat dan menghasilkan perubahan yang dimaksud. Reach bukan outcome akhir; pilih metrik sesuai objective seperti recall, comprehension, consideration, preference, branded search, qualified action, atau brand lift. Learning agenda merumuskan pertanyaan yang bisa memengaruhi keputusan berikutnya, bukan sekadar laporan angka.",
   example:"SIMULASI — campaign menghasilkan reach tinggi tetapi recall rendah pada target. Penelusuran menemukan frequency tidak merata dan pesan utama tidak terbaca pada creative. Rekomendasi harus membedakan delivery issue dan message issue.",
   actions:["Definisikan objective, KPI, baseline, population, measurement source, dan time window.","Pilih metode: brand tracking, brand lift, survey, experiment, search/behavior signal, atau post-campaign analysis.","Buat learning question, hypothesis, guardrail, decision threshold, dan owner."],
   practice:"Rancang effectiveness framework dan learning agenda satu kuartal. Sertakan primary/secondary/guardrail KPI, instrument, sampling, timing, method limitations, data owner, dan keputusan yang akan diambil.",
   qaFocus:["memilih metode measurement sesuai communication objective","membedakan reach/delivery dengan change in perception or behaviour","menyusun learning question yang memengaruhi keputusan berikutnya"],
   terms:[["Brand lift","Perubahan indikator brand antara kelompok exposed dan comparison/control."],["Learning agenda","Daftar pertanyaan terstruktur untuk memperbaiki strategi."],["Measurement window","Rentang waktu ketika outcome diukur."]]
  },
  {
   concept:"Capstone harus memperlihatkan hubungan utuh antara brief, research, insight, proposition, journey, channel role, message architecture, creative handoff, dan effectiveness. Rekomendasi harus menjelaskan alasan dan trade-off, bukan hanya mengumpulkan slide. Angka forecast/simulasi wajib diberi label, sementara hasil real hanya boleh digunakan bila sumber dan permission jelas.",
   example:"SIMULASI — brand Indonesia ingin meluncurkan kategori baru selama 12 minggu. Tim perlu menyusun communication strategy dengan prioritas audience, moment, platform idea, channel mix, creative brief, governance, measurement, dan learning agenda.",
   actions:["Sintesis brief, audience evidence, insight, positioning, dan communication objective.","Bangun journey, touchpoint, channel-role, message architecture, dan creative/activation handoff.","Susun effectiveness plan, risks, assumptions, executive story, dan next-quarter learning agenda."],
   practice:"Buat capstone 10–12 slide + workbook: challenge, evidence log, audience, insight, positioning, journey, channel role, message architecture, creative brief, orchestration, measurement, risk, dan learning agenda. Presentasikan 5 menit dan tandai data sintetis.",
   qaFocus:["menunjukkan hubungan evidence → insight → strategy → execution","mempertanggungjawabkan trade-off dalam pemilihan channel dan message","memisahkan forecast/synthetic data dari hasil aktual"],
   terms:[["Integrated strategy deck","Presentasi terstruktur dari challenge sampai execution dan measurement."],["Evidence log","Catatan sumber, metode, periode, serta batas interpretasi."],["Trade-off","Konsekuensi yang diterima ketika memilih satu pendekatan dibanding alternatif."]]
  }
 ]
};
ROLE_GUIDES.media = {
 scope:"Media Planner / Digital Planner menerjemahkan brief menjadi rencana media lintas channel: audience, objectives, investment, reach/frequency, budget, timing, inventory, forecast, buying handoff, dan post-buy evaluation. Planner bukan otomatis buyer, trafficker, atau campaign operator; peran intinya membuat rencana yang feasible, transparent, dan dapat dipertanggungjawabkan.",
 workflow:[
  "<b>Translate the brief.</b> Turunkan business objective menjadi media objective, target audience, KPI, budget, period, geography, dan restrictions.",
  "<b>Evaluate the media landscape.</b> Bandingkan channel/inventory, audience quality, reach, cost, format, availability, brand safety, dan measurement.",
  "<b>Build the investment model.</b> Buat media mix, budget scenarios, reach/frequency estimate, assumptions, and sensitivity analysis.",
  "<b>Plan delivery and handoff.</b> Buat flowchart, flighting, booking brief, owner, creative specs, tracking, and contingency.",
  "<b>Evaluate and improve.</b> Audit planned vs actual, delivery quality, effectiveness, value, and recommendations for the next flight."
 ],
 qa:[
  "Objective media harus diturunkan dari business/communication goal dan target audience. Setiap KPI perlu formula, unit, denominator, time window, source, dan alasan relevansinya.",
  "Forecast bukan angka pasti. Cantumkan inventory, rate, CPM/CPP, reach/frequency assumptions, duplication, geography, budget, seasonality, delivery constraints, dan sensitivity range.",
  "Post-buy tidak hanya membandingkan spend vs plan; periksa actual delivery, eligible audience, quality, pacing, variance, billable basis, outcome, source reliability, dan rekomendasi."
 ],
 glossary:[
  ["Media objective","Peran media yang menghubungkan business/communication objective ke delivery."],["Media mix","Kombinasi channel dan placement untuk mencapai objective."],["Reach","Jumlah orang unik yang terpapar dalam definisi periode."],["Frequency","Rata-rata jumlah exposure per orang."],["GRP","Gross Rating Points; jumlah rating points yang merepresentasikan reach × frequency."],["CPP","Cost per rating point."],["CPM","Biaya per seribu impressions."],["Flighting","Pola waktu pengeluaran atau penayangan media."],["Media flowchart","Visualisasi channel, format, budget, timing, dan weight."],["Post-buy","Evaluasi hasil aktual dibanding plan dan tujuan."]
 ],
 chapters:[
  {concept:"Brief media harus mengubah tujuan bisnis atau komunikasi menjadi kebutuhan delivery yang bisa direncanakan. Planner perlu mengklarifikasi target, geography, audience, timing, budget, seasonality, mandatories, inventory, dan conversion/brand outcome. Jangan mengubah KPI bisnis langsung menjadi CPM tanpa memahami journey dan peran media.",example:"SIMULASI — brand snack ingin menaikkan trial di tiga kota selama 8 minggu. Tim perlu memastikan ketersediaan stok, target household, seasonality Ramadan, budget net/gross, target reach, dan kanal untuk discovery serta purchase.",actions:["Restate business objective menjadi media task dan audience definition.","Susun requirement sheet: geography, timing, budget, format, KPI, restrictions, stock, and measurement.","Catat pertanyaan klarifikasi dan asumsi yang belum tervalidasi."],practice:"Buat media requirement sheet dari satu brief: objective, audience, geography, timing, budget basis, inventory need, KPI, creative mandatories, stock/sales constraints, measurement, dan open questions.",qaFocus:["mengubah objective menjadi media task yang terukur","mengidentifikasi informasi brief yang hilang","membedakan budget gross/net dan media KPI"],terms:[["Net media budget","Budget yang tersedia untuk media setelah fee/biaya yang ditetapkan."],["Audience definition","Definisi populasi yang ingin dijangkau."],["Mandatories","Ketentuan yang wajib dipenuhi dalam rencana media."]]},
  {concept:"Audience-media planning menghubungkan siapa yang dituju dengan kebiasaan konsumsi media, context, attention, dan opportunity untuk mencapai mereka. Data survey, panel, platform insights, first-party data, dan research report memiliki cakupan berbeda; planner harus mencatat universe, sample, periode, dan kemungkinan bias.",example:"SIMULASI — audience 18–24 menggunakan short video untuk discovery tetapi melakukan perbandingan harga di search dan marketplace. Planner memerlukan cross-media profile, bukan menganggap satu platform mewakili seluruh journey.",actions:["Definisikan audience segment dan market universe.","Bandingkan media consumption dengan sumber, periode, sample, dan geography.","Ubah temuan menjadi channel opportunity dan reach/duplication assumptions."],practice:"Buat audience-media profile dua segmen dengan media habits, daypart, device, content context, platform signals, reach data source, sample/limitations, dan planning implications.",qaFocus:["menilai kualitas audience data dan sample","menghubungkan media consumption ke channel choices","menghindari double counting audience antar platform"],terms:[["Universe","Populasi yang dicakup oleh data/rating."],["Duplication","Orang yang terhitung lebih dari sekali di beberapa channel."],["Daypart","Bagian waktu dalam hari yang digunakan untuk perencanaan media."]]},
  {concept:"Media landscape mencakup digital, broadcast, OOH/DOOH, print, cinema, retail media, audio, dan publisher-owned inventory. Evaluasi bukan sekadar memilih platform populer; lihat audience, content context, availability, format, viewability, brand safety, measurement, rate, dan operational fit. Distinguish media owner, sales house, publisher, reseller, agency, and ad-tech intermediary.",example:"SIMULASI — dua publisher menawarkan inventory premium. Publisher A memiliki affinity tinggi namun kapasitas terbatas; B punya volume besar tetapi audience overlap tinggi. Pilihan memerlukan comparison matrix dan delivery assumptions.",actions:["Petakan channel dan supply owner untuk target market.","Audit media kit, audience methodology, placements, format, availability, exclusions, and rate.","Bandingkan quality-adjusted value, not CPM alone."],practice:"Buat channel evaluation matrix untuk minimal empat opsi (search, social, publisher, retail/OOH): audience fit, role, format, inventory, cost, availability, measurement, risk, and recommendation.",qaFocus:["membandingkan inventory berdasarkan value, bukan rate semata","mengetahui siapa pemilik/seller inventory","mengidentifikasi measurement gaps antar channel"],terms:[["Media owner","Pihak yang memiliki atau menjual inventory media."],["Sales house","Entitas komersial yang mewakili penjualan inventory."],["Inventory","Kesempatan penayangan/placement yang tersedia."]]},
  {concept:"Media objective memberi tugas spesifik ke setiap channel: reach, frequency, consideration, demand capture, traffic, conversion, or retention support. KPI harus sesuai role. Reach objective butuh unique reach/frequency/quality; response objective butuh qualified traffic/action; sales outcomes memerlukan conversion definitions dan attribution caveats. Jangan membandingkan CTR sebagai satu-satunya ukuran lintas channel.",example:"SIMULASI — brand awareness memerlukan unique reach pada target, sementara search hanya tersedia saat audience menunjukkan intent. Jika semua kanal dinilai dengan last-click sales, kontribusi awareness akan diremehkan.",actions:["Turunkan communication role menjadi media objective per channel.","Pilih primary, secondary, diagnostic, and guardrail KPIs.","Definisikan formula, window, source, owner, and benchmark logic."],practice:"Buat KPI-channel sheet: objective, channel role, primary metric, diagnostic metric, formula, unit, source, target basis, reporting cadence, and guardrail. Jelaskan metrik yang tidak boleh dibandingkan langsung.",qaFocus:["mencocokkan KPI dengan channel objective","mendefinisikan formula dan denominator","menghindari vanity metrics atau perbandingan metrik tidak sepadan"],terms:[["Primary KPI","Ukuran utama yang menentukan keberhasilan objective."],["Diagnostic metric","Metrik untuk menjelaskan perubahan pada primary KPI."],["Guardrail","Batas kualitas agar optimasi tidak merusak outcome lain."]]},
  {concept:"Budget allocation adalah keputusan investasi, bukan pembagian persentase rata. Alokasi mempertimbangkan audience reach, marginal return, channel role, inventory, cost, saturation, creative capacity, measurement confidence, and business constraint. Scenario planning membandingkan base, conservative, dan stretch serta mencatat apa yang dikorbankan bila budget berubah.",example:"SIMULASI — budget Rp1 miliar: Search hanya memiliki incremental volume terbatas, social video punya reach tetapi memerlukan creative variants, retail media punya purchase context, dan publisher partnership memiliki premium audience. Planner membuat scenario berdasarkan trade-off, bukan trend.",actions:["Tentukan budget basis, fee, tax, production, and working media separation.","Buat allocation model dan scenarios dengan input cost/volume.","Uji sensitivity terhadap CPM, CPC, CVR, reach duplication, and inventory caps."],practice:"Bangun media mix dan budget workbook dengan base/conservative/stretch. Cantumkan objective, spend per channel, assumptions, forecast output, marginal trade-off, risk, and reallocation trigger.",qaFocus:["mengalokasikan berdasarkan peran dan marginal return","menghitung asumsi forecast secara transparan","menjelaskan trade-off ketika budget dipotong/ditambah"],terms:[["Working media","Belanja yang langsung dialokasikan ke inventory media."],["Marginal return","Perubahan outcome dari tambahan satu unit investasi."],["Scenario analysis","Perbandingan beberapa kemungkinan asumsi dan hasil."]]},
  {concept:"Reach, frequency, GRP/TRP, CPM, CPP, CPC, dan forecast tidak dapat dipakai tanpa definisi universe dan basis data. Untuk tradisional, rating points dan audience measurement punya metodologi tertentu; untuk digital, impression/reach bukan otomatis perhatian atau unique cross-media reach. Setiap forecast harus menyebut rates, audience source, period, duplication, gross/net, and delivery conditions.",example:"SIMULASI — 1 juta impressions dengan frequency 5 tidak berarti satu juta orang; estimated unique reach bisa jauh lebih rendah. Planner mengestimasi reach secara terpisah dan menjelaskan asumsi cross-platform deduplication yang belum tersedia.",actions:["Tulis formula dan denominator untuk setiap metrik.","Catat rating universe, panel/data source, rates, geography, and period.","Buat range forecast serta sensitivity dan limitation."],practice:"Buat forecast model dari budget dan rate card hipotetis: CPM, impressions, reach estimate, average frequency, GRP/CPP jika relevan, dan scenario. Tandai semua angka sebagai SIMULATED dan tulis asumsi.",qaFocus:["memahami perbedaan reach, impressions, dan frequency","menggunakan GRP/CPP hanya pada basis audience yang sesuai","menjelaskan batas cross-media deduplication"],terms:[["TRP","Target Rating Points pada target audience tertentu."],["CPP","Biaya untuk memperoleh satu rating point."],["Frequency cap","Batas exposure yang diizinkan per audience/user dalam periode."]]},
  {concept:"Flowchart dan flighting menerjemahkan media mix menjadi jadwal delivery. Pola continuity, flighting, pulsing, dan burst harus sesuai seasonality, inventory, audience behavior, promotion, and conversion cycle. Scenario planning harus menunjukkan tanggal, budget, weighting, format, target, dependency, dan tindakan saat delivery under/over.",example:"SIMULASI — e-commerce campaign menambah spend saat payday dan promo 11.11; brand awareness perlu always-on baseline agar tidak hilang sepenuhnya antara burst. Planner menjelaskan bobot tiap fase.",actions:["Susun channel/format/date/spend/weight dalam flowchart.","Tentukan continuity, flight, burst, dan pacing assumptions.","Tambahkan best/base/worst scenario dan contingency triggers."],practice:"Buat media flowchart 8 minggu lengkap dengan spend, platform, format, audience, objective, creative dependency, KPI, weekly weight, dan skenario perubahan tanggal atau budget.",qaFocus:["memilih pola flighting sesuai purchase cycle","menghubungkan tanggal, budget, dan creative readiness","menetapkan tindakan jika pacing atau inventory berubah"],terms:[["Continuity","Pola kehadiran media yang relatif konsisten."],["Pulsing","Baseline always-on dengan periode intensitas lebih tinggi."],["Flighting","Pola burst dengan periode penayangan dan jeda."]]},
  {concept:"Buying brief merupakan kontrak operasional antara planner dan buyer/investment/ad ops. Brief harus membawa objective, audience, inventory, budget, dates, specs, KPIs, tracking, exclusions, creative delivery, approval, dan billing requirements. Handoff yang buruk menimbulkan perubahan mendadak, misspec, dan dispute; planner perlu menjaga satu source of truth.",example:"SIMULASI — plan memesan sponsorship dengan format rich media tetapi creative delivery belum mendapat approval. Buyer tidak bisa memastikan booking dan Ad Ops tak dapat menyiapkan tags. Handoff dependency harus terlihat sebelum IO diterbitkan.",actions:["Buat buy brief yang konsisten dengan media plan version.","Tetapkan vendor, placement, rate, commitment, creative deadline, tracking, owner, and approvals.","Lakukan handoff meeting dan sign-off; simpan perubahan serta exceptions."],practice:"Susun buying brief + handoff checklist untuk tiga placement. Cantumkan IO/booking need, spec, tag/tracker, dates, rate, delivery commitment, makegood, approval, and escalation.",qaFocus:["membedakan planning decisions dan buying execution","memberi detail yang dibutuhkan buyer dan Ad Ops","memastikan approval, version, dan dependencies terlacak"],terms:[["Insertion Order","Dokumen pemesanan media yang merinci placement, schedule, rate, dan terms."],["Handoff","Penyerahan scope dan artefak antar tim."],["Makegood","Kompensasi/penayangan pengganti atas delivery yang tidak sesuai kontrak."]]},
  {concept:"Post-campaign analysis membandingkan plan dan actual pada basis yang setara. Delivery, reach, frequency, impression quality, audience, timing, spend, and outcome perlu dibaca bersama. Perbedaan reported result tidak otomatis berarti vendor error; periksa event definition, timezone, attribution, billing basis, and data latency. Gunakan temuan untuk memperbaiki flight berikutnya.",example:"SIMULASI — campaign mencapai impression target tetapi underdelivered unique reach dan frequency terlalu tinggi. Tim memeriksa audience overlap, placement mix, pacing, dan platform limitations sebelum membuat rekomendasi.",actions:["Reconcile plan vs actual dan normalisasi unit/window.","Segmentasikan variance berdasarkan channel, placement, date, audience, creative, and outcome.","Tulis root-cause hypothesis, confidence, commercial implication, and next-flight action."],practice:"Buat post-campaign review: planned/actual, variance, delivery quality, reach/frequency, KPI outcome, limitation, root cause, vendor action, and three next-flight recommendations.",qaFocus:["membandingkan actual dengan plan berdasarkan definisi sepadan","membedakan delivery variance dari outcome shortfall","membuat rekomendasi yang bisa dieksekusi pada flight berikutnya"],terms:[["Post-buy","Evaluasi hasil media setelah campaign berjalan."],["Variance","Selisih antara plan/target dan actual."],["Reconciliation","Pencocokan data delivery, booking, dan billing."]]},
  {concept:"Capstone Media Planning harus menggabungkan brief, audience/media evidence, channel objective, mix, budget, forecast, flighting, buying handoff, measurement, risk, and post-buy logic. Presentasi harus menjelaskan keputusan, trade-off, data source, assumptions, and contingency. Planner tidak perlu mengoperasikan setiap platform, tetapi harus memahami implikasi teknis dan komersial rencananya.",example:"SIMULASI — kategori consumer goods meluncurkan varian baru di Indonesia dengan budget Rp1,2 miliar dan target 3 kota. Peserta merancang mix digital, commerce, publisher, serta opsi offline sesuai audience, inventory, and measurement ability.",actions:["Sintesiskan brief, audience, objectives, channel roles, and evidence.","Bangun budget and forecast scenarios, flowchart, and buy brief.","Susun measurement, risks, contingency, post-buy review, and executive deck."],practice:"Buat capstone 10–12 slide + workbook: media brief, audience evidence, landscape matrix, KPI tree, media mix, budget, forecast, flowchart, buying brief, measurement plan, risk, dan post-buy learning agenda. Label SIMULATED.",qaFocus:["menunjukkan konsistensi brief hingga allocation dan KPI","menjelaskan assumptions dan limitations forecast","menyampaikan trade-offs dan next actions secara executive-ready"],terms:[["Media plan","Dokumen rancangan audience, channel, budget, timing, and measurement."],["Media flowchart","Timeline terstruktur untuk media delivery."],["Investment rationale","Alasan komersial di balik alokasi budget."]]}
 ]
};
ROLE_GUIDES.paidsearch = {
 scope:"Paid Search / SEM Specialist mengelola paid search dari query intent sampai conversion measurement: keyword research, account structure, ad copy, bidding, budget, landing-page match, conversion actions, search-term hygiene, reporting, and testing. Search campaign bukan sekadar memasukkan banyak keyword atau menaikkan bid; relevansi, query quality, economics, and measurement menentukan kualitas keputusan.",
 workflow:[
  "<b>Read intent.</b> Pahami kebutuhan di balik query, market, competition, search volume, and landing page fit.",
  "<b>Build structure.</b> Atur campaign, ad group, keywords, match types, negative lists, budgets, naming, and geographic/language settings.",
  "<b>Create relevant ads.</b> Susun RSA/assets sesuai intent, promise, proof, CTA, and landing page.",
  "<b>Measure conversions.</b> Definisikan conversion actions, enhanced/offline signals, consent, deduplication, and source of truth.",
  "<b>Optimize economically.</b> Analisis search terms, CPC, CVR, CPA, ROAS/margin, impression share, quality signals, and tests."
 ],
 qa:[
  "Keyword grouping harus mengikuti intent dan landing-page fit. Volume tinggi tanpa commercial relevance dapat menghasilkan spend terbuang; dokumentasikan query intent, match type, and exclusions.",
  "Diagnosis search dilakukan berurutan: search terms, eligibility, budget/rank, ad relevance, landing page, conversion tracking, and economics. Jangan mengubah bid sebelum tahu sumber masalah.",
  "Conversion action harus mewakili outcome dan memiliki trigger, value, currency, deduplication, consent, and reporting window yang jelas. Simpan test evidence sebelum memakai data untuk bidding."
 ],
 glossary:[
  ["Search term","Query aktual yang diketik pengguna."],["Keyword","Istilah target yang dipakai untuk mengatur eligibility iklan."],["Match type","Aturan cakupan query yang dapat memicu keyword."],["Negative keyword","Kata/intent yang mengecualikan iklan dari pencarian tidak relevan."],["RSA","Responsive Search Ad yang mengkombinasikan headline dan description."],["Ad Rank","Mekanisme yang menentukan eligibility dan posisi iklan."],["Quality Score","Diagnostic estimate atas relevance/experience, bukan outcome tunggal."],["Impression share","Impressions yang diperoleh dibanding impressions eligible."],["Enhanced Conversions","Peningkatan akurasi conversion measurement menggunakan data first-party yang di-hash sesuai kebijakan."],["Offline conversion import","Pengiriman outcome offline yang terhubung dengan interaksi iklan."]
 ],
 chapters:[
  {concept:"Paid search auction menghubungkan query, advertiser eligibility, bid, ad quality, context, and expected impact. Search specialist perlu memahami bagaimana Google Ads, Microsoft Advertising, dan search ad servers berbeda serta bagaimana auction memengaruhi reach, CPC, and impression share. Objective bisnis harus jelas sebelum memilih campaign type atau bidding.",example:"SIMULASI — dua advertiser menargetkan query 'kelas bahasa Inggris online'. Bid yang lebih tinggi belum tentu menang jika ad relevance dan landing experience lebih buruk. Specialist perlu membaca auction signals, not only bid amount.",actions:["Petakan advertiser, platform, auction, ad rank, query, and landing page.","Definisikan account access, billing, policy, geography, and conversion destination.","Buat glossary untuk impression, click, CPC, CTR, conversion action, and ad rank."],practice:"Buat search-ad ecosystem map, account-readiness checklist, dan glossary. Bandingkan Google Search dan Microsoft Search dari sisi inventory, audience, targeting, and reporting.",qaFocus:["menjelaskan auction dan ad eligibility","memahami perbedaan query, keyword, impression, click, dan conversion","mengidentifikasi faktor selain bid yang memengaruhi auction"],terms:[["Auction","Proses kompetitif menentukan iklan yang dapat tampil."],["Ad Rank","Sistem penilaian untuk eligibility/posisi iklan."],["CPC","Biaya rata-rata per klik."]]},
  {concept:"Search intent mengelompokkan kebutuhan pengguna seperti informational, commercial investigation, transactional, and navigational. Keyword research memerlukan relevance, volume, competition, SERP format, CPC context, and landing page fit. Jangan mengejar volume tanpa mempertimbangkan conversion potential, brand safety, and business economics.",example:"SIMULASI — 'cara memilih asuransi mobil' bersifat informational/commercial research, sedangkan 'beli asuransi mobil online' lebih dekat ke transactional. Keduanya membutuhkan ad copy, landing page, and conversion expectation yang berbeda.",actions:["Kumpulkan seed terms, search suggestions, competitor terms, and SERP evidence.","Kelompokkan keyword berdasarkan intent, theme, commercial value, and landing page destination.","Dokumentasikan source, geography, date range, volume limitations, and negative opportunities."],practice:"Buat keyword research sheet minimal 30 query: intent, volume source, competition, CPC proxy, relevance, funnel stage, landing page, competitor pattern, negative candidate, and priority.",qaFocus:["membedakan intent dan kata yang terlihat mirip","menilai keyword dengan relevance dan conversion potential","mendokumentasikan source dan periode data keyword"],terms:[["Informational intent","Kebutuhan mencari penjelasan atau informasi."],["Transactional intent","Kebutuhan menyelesaikan tindakan atau transaksi."],["SERP","Search Engine Results Page."]]},
  {concept:"Account structure menjaga hubungan antara objective, budget, geography, language, audience, keywords, ads, and landing pages tetap jelas. Campaign sebaiknya dipisah ketika kebutuhan budget, market, objective, or control memang berbeda. Terlalu banyak campaign/ad group dapat memecah data dan memperlambat learning.",example:"SIMULASI — retailer memiliki 3 kategori dengan margin, location, and landing pages berbeda. Satu campaign besar akan menyamarkan budget allocation; terlalu banyak campaign per keyword akan memecah volume. Struktur harus menyeimbangkan control dan data density.",actions:["Tentukan naming convention yang mencakup brand, market, objective, product, and period.","Rancang campaign/ad group dari intent, budget control, geography, and landing-page alignment.","Buat mapping keyword → ad group → ad → landing page dan cek overlap."],practice:"Buat account architecture untuk satu brand: campaign hierarchy, naming rules, budget ownership, geo/language, ad groups, keyword themes, negative lists, landing URLs, and change governance.",qaFocus:["memisahkan struktur karena kebutuhan kontrol yang nyata","menjaga data tidak terlalu terfragmentasi","memastikan keyword, ad copy, dan landing page satu intent"],terms:[["Campaign","Unit pengelolaan objective/budget pada platform."],["Ad group","Kelompok keyword dan iklan dengan tema relevan."],["Naming taxonomy","Aturan penamaan konsisten untuk audit dan reporting."]]},
  {concept:"Match types mengatur seberapa luas query dapat memicu keyword; negative keywords membantu menghindari traffic tidak relevan. Search terms report adalah bukti perilaku actual, bukan asumsi planner. Search-term hygiene harus menyeimbangkan coverage dan precision, serta mempertimbangkan close variants, privacy thresholds, and query volume.",example:"SIMULASI — keyword broad 'kursus online' memicu pencarian 'kursus gratis pemerintah' meskipun brand menjual kelas premium. Specialist mengevaluasi search terms, conversion quality, and negative list sebelum menambah keyword baru.",actions:["Tetapkan intent boundary untuk setiap keyword theme.","Review search terms dan kelompokkan relevant, irrelevant, competitor, and new opportunity.","Tambahkan negative keywords dengan scope account/campaign/ad group dan cek potensi overblocking."],practice:"Buat match-type plan, negative keyword list, dan weekly search-term review log menggunakan dataset sintetis. Setiap exclusion harus punya reason, scope, and QA.",qaFocus:["memilih match type berdasarkan coverage dan control","menggunakan search-term evidence sebelum menambah/mengecualikan query","menghindari negative keyword yang menghalangi intent relevan"],terms:[["Broad match","Match type yang dapat menjangkau pencarian terkait lebih luas."],["Exact match","Match type dengan kontrol intent lebih ketat."],["Negative keyword","Pengecualian query yang tidak relevan."]]},
  {concept:"Ad copy dan assets menerjemahkan intent menjadi janji yang relevan. Responsive Search Ads memerlukan variasi headline/description yang saling melengkapi, bukti, differentiator, CTA, and policy compliance. Quality Score bukan scorecard bisnis; periksa relevance, expected CTR, landing-page experience, conversion quality, and actual cost.",example:"SIMULASI — iklan menjanjikan 'gratis konsultasi' tetapi landing page justru menampilkan formulir demo berbayar. Message mismatch menurunkan trust. Perbaiki promise/CTA dan pastikan offer benar-benar tersedia.",actions:["Buat message matrix: intent, pain point, benefit, proof, objection, CTA.","Tulis headline/description assets yang berbeda tetapi koheren; hindari klaim tak terbukti.","Review policy, destination URL, mobile experience, and landing-page content."],practice:"Tulis dua RSA concept untuk tiga intent cluster. Sertakan headline set, descriptions, assets, proof, CTA, URL, policy checklist, and message-match scoring.",qaFocus:["menjaga promise ad sesuai landing page","membuat variasi creative yang menguji proposition, bukan sekadar sinonim","memisahkan Quality Score diagnostic dari bisnis outcome"],terms:[["RSA","Responsive Search Ad."],["Ad asset","Elemen tambahan atau bagian copy yang memperkaya iklan."],["Message match","Konsistensi pesan antara query, iklan, dan landing page."]]},
  {concept:"Campaign types dan bidding strategies harus dipilih menurut business objective, conversion signal, budget, and data readiness. Manual bidding dan automated bidding memiliki trade-offs; tCPA/tROAS membutuhkan conversion data dan value yang valid. Budget pacing perlu memperhitungkan seasonality, search volume, lost impression share, and auction competition.",example:"SIMULASI — campaign baru dengan 5 conversion per bulan belum cukup stabil untuk mengandalkan target ROAS agresif. Specialist menentukan learning expectation, conversion action, and budget constraints sebelum mengaktifkan automated bidding.",actions:["Pilih campaign type sesuai search inventory, objective, and business model.","Evaluasi conversion volume/quality, value tracking, and data readiness sebelum bid strategy.","Buat pacing sheet dan rules untuk overspend, underspend, and sudden CPC/CVR changes."],practice:"Rancang bidding and budget plan: campaign type, bid strategy, learning assumptions, target CPA/ROAS basis, daily/monthly budgets, pacing limits, seasonality, and reallocation triggers.",qaFocus:["menentukan kapan automated bidding layak digunakan","menjelaskan hubungan conversion signal dengan bid learning","membuat pacing guardrail yang sesuai budget dan demand"],terms:[["tCPA","Target cost per acquisition bidding."],["tROAS","Target return on ad spend bidding."],["Pacing","Pengendalian spend terhadap budget dan waktu."]]},
  {concept:"Conversion tracking menghubungkan klik/search activity dengan tindakan bernilai. Definisikan conversion action, primary/secondary status, counting method, value, attribution window, enhanced conversions, consent, and offline outcome mapping. Offline lead/sale import harus menjaga ID match, event quality, duplicate handling, and privacy. Tracking plan bukan berarti implementasi sudah live.",example:"SIMULASI — search leads form submit banyak tetapi hanya sedikit qualified lead. CRM qualification status perlu dipetakan ke offline conversion event; tanpa definisi quality, bidding dapat mengejar form spam.",actions:["Map business outcome ke conversion actions and event parameters.","Audit tag, URL, consent, deduplication, conversion window, and test events.","Rancang offline feedback loop dengan CRM status, click IDs, and privacy controls."],practice:"Buat conversion measurement plan untuk form lead dan qualified sale: event spec, values, counting, attribution, consent, enhanced conversions, offline import, test cases, and QA evidence.",qaFocus:["membedakan form submission dengan qualified conversion","menentukan conversion action dan counting rules","menjaga consent, deduplication, dan offline event quality"],terms:[["Conversion action","Event/tindakan yang dihitung sebagai outcome."],["Click ID","Identifier untuk menghubungkan click dengan downstream conversion."],["Offline conversion","Outcome terjadi di luar platform, misalnya closed sale dalam CRM."]]},
  {concept:"Search-term analysis, Quality Score, and Impression Share are diagnostic instruments. Search terms show intent actually matched; Quality Score components are diagnostic estimates; impression share lost to budget and rank point to different constraints. Use segments, match types, device, geography, and time before choosing expansion, negative, bid, or landing-page changes.",example:"SIMULASI — impression share turun. Jika lost IS budget tinggi, bid adjustment alone may not fix it; if lost IS rank high, improve relevance/competitiveness. Check conversion quality and margin before increasing budget.",actions:["Segment search-term report by intent, conversion, cost, and match type.","Separate lost impression share due to budget vs rank.","Translate diagnostic findings into controlled changes and monitor side effects."],practice:"Isi diagnostic worksheet untuk satu campaign sintetis: query groups, QS components, lost IS budget/rank, device/geo splits, CPA/CVR, and prioritized next actions.",qaFocus:["membedakan lost impression share karena budget dan rank","menggunakan Quality Score sebagai diagnostic, bukan north-star metric","memastikan query expansion tidak menurunkan qualified conversion"],terms:[["Impression share","Porsi impressions yang diperoleh dari peluang eligible."],["Lost IS budget","Impression share yang hilang akibat keterbatasan budget."],["Expected CTR","Estimasi probabilitas klik relatif terhadap iklan lain yang eligible."]]},
  {concept:"Optimization memerlukan rutinitas diagnosis, controlled changes, and reporting. Test ad copy, landing page, bid strategy, and keyword themes with clear hypotheses, baseline, observation window, and guardrails. Jangan menyimpulkan perubahan akibat satu faktor jika budget, competition, promo, and tracking juga berubah.",example:"SIMULASI — CPC turun 12% tetapi CPA naik 25%. Tim memeriksa search term mix, CVR, landing-page errors, and lead quality sebelum menambah budget atau mengganti bid strategy.",actions:["Tentukan perubahan dengan hypothesis dan primary/guardrail metric.","Bandingkan segment and baseline untuk mengidentifikasi driver.","Catat change log, result, confidence, limitation, and next test."],practice:"Buat weekly optimization report dari dataset sintetis dengan observation, diagnosis, evidence, action, owner, guardrail, result, and next test. Label semua angka.",qaFocus:["membedakan korelasi dengan effect of a change","menggunakan primary metric dan guardrail saat testing","membuat report yang menjelaskan why, not only what"],terms:[["Change log","Catatan perubahan campaign dan waktu implementasinya."],["Guardrail metric","Metrik penjaga kualitas saat mengoptimalkan outcome utama."],["Search-term mining","Proses menemukan insight/keyword/exclusion dari query aktual."]]},
  {concept:"Capstone menguji seluruh search workflow dari research sampai reporting. Portfolio harus menunjukkan alasan pemilihan keyword, struktur, creative, bid strategy, measurement, and optimization. Forecast atau synthetic performance tidak boleh ditampilkan sebagai client result; cantumkan formula, assumptions, and data limitations.",example:"SIMULASI — campaign untuk layanan pendidikan dengan tiga kota, empat kategori program, dan budget hipotetis. Buat intent architecture, ads, conversion measurement, and optimization plan.",actions:["Susun business/context brief and keyword-intent map.","Bangun account, ads, landing-page mapping, bid and budget plan.","Define tracking, QA, reporting, diagnostic, and recommendation."],practice:"Buat capstone deck + workbook: brief, query map, account architecture, negative keywords, RSA, bid plan, conversion plan, QA, synthetic performance, optimization memo, and assumptions log.",qaFocus:["menjaga konsistensi dari intent hingga conversion measurement","menunjukkan keputusan dengan data dan assumptions","menyajikan synthetic output dengan label dan batas yang jelas"],terms:[["Search capstone","Paket kerja utuh untuk merancang dan mengevaluasi paid search."],["Optimization memo","Dokumen diagnosis dan rekomendasi perubahan."],["Assumption log","Daftar asumsi, bukti, confidence, dan cara validasinya."]]}
 ]
};
ROLE_GUIDES.programmatic = {
 scope:"Programmatic Specialist mengelola pembelian digital inventory melalui DSP dan mekanisme auction/deal. Kompetensinya mencakup supply chain, OpenRTB, identity/privacy, DSP architecture, inventory/deals, bidding/pacing, verification, trafficking, measurement, and supply quality. Programmatic berbeda dari paid social/search dan berbeda dari Ad Ops; specialist ini mengambil keputusan buying dan delivery melalui platform programmatic.",
 workflow:[
  "<b>Map the supply chain.</b> Pahami advertiser, agency, DSP, exchange, SSP, publisher ad server, data provider, and verification provider.",
  "<b>Plan audience and inventory.</b> Pilih first-party/contextual/third-party signals, deal type, formats, privacy basis, and supply-path controls.",
  "<b>Build and activate.</b> Struktur campaign/IO/line item, creative, trackers, bidding, budget, frequency, and flight.",
  "<b>Monitor quality and delivery.</b> Pacing, win rate, viewability, IVT, brand safety, deal delivery, and discrepancy.",
  "<b>Evaluate and optimise.</b> Reconcile source data, measurement, marginal outcomes, supply quality, and post-campaign learnings."
 ],
 qa:[
  "Setiap impression melalui rangkaian buyer–DSP–exchange–SSP–publisher. Mapping fee, reseller, ads.txt/sellers.json, timeout, and deal terms membantu menemukan supply leakage dan risiko inventory.",
  "Bid strategy harus mempertimbangkan goal, CPM floor, auction dynamics, audience signal, budget, win rate, and frequency. Jangan mengubah bid tanpa melihat delivery, inventory, and conversion signal.",
  "Quality tidak cukup dinilai dari CPM/CTR. Periksa viewability definition, eligible/measurable impressions, IVT filtering, brand suitability, publisher transparency, and outcome."
 ],
 glossary:[
  ["DSP","Platform sisi pembeli untuk merencanakan dan membeli digital inventory."],["SSP","Platform sisi publisher untuk mengelola dan menjual inventory."],["Ad exchange","Marketplace yang menghubungkan demand dan supply."],["OpenRTB","Standar protokol untuk pertukaran bid request/response."],["SPO","Supply Path Optimization."],["PMP","Private Marketplace deal."],["PG","Programmatic Guaranteed."],["Viewability","Pengukuran apakah iklan memenuhi kriteria terlihat."],["IVT","Invalid Traffic."],["Floodlight","Tag/activity measurement dalam Campaign Manager 360."]
 ],
 chapters:[
  {concept:"Programmatic advertising mengotomasi pembelian inventory digital melalui platform dan auction. DSP mengelola demand; SSP membantu publisher mengelola supply; exchange menghubungkan keduanya; ad server mengatur ad delivery. Peran dan biaya setiap intermediary perlu dipahami karena berdampak pada transparency, latency, inventory quality, and net media value.",example:"SIMULASI — advertiser membelanjakan Rp100 juta melalui DSP, tetapi report publisher dan DSP menunjukkan volume berbeda. Tim memetakan fee, exchange, SSP, reseller, and ad server untuk mengetahui perbedaan basis delivery.",actions:["Gambar alur advertiser → agency → DSP → exchange → SSP → publisher/ad server.","Tandai data, fee, control, and responsibility at every node.","Bandingkan DSP reporting dengan publisher proof and contract basis."],practice:"Buat supply-chain map yang menyebut platform, owner, data exchanged, cost/fee, transparency evidence, and failure points. Sertakan satu sample impression flow.",qaFocus:["membedakan DSP, SSP, exchange, dan ad server","menjelaskan peran tiap intermediary dalam impression flow","memetakan di mana fee dan data visibility berkurang"],terms:[["Supply chain","Rangkaian teknologi dan pihak dalam transaksi inventory."],["Bid request","Permintaan data/parameter untuk sebuah kesempatan iklan."],["Bid response","Tawaran dari buyer kepada auction."]]},
  {concept:"RTB adalah proses lelang per kesempatan impression. OpenRTB menstandarkan struktur bid request/response agar buyer dan seller dapat bertukar informasi tentang placement, device, user/context signals, and auction. Supply Path Optimization mengevaluasi jalur supply berdasarkan transparency, fees, duplication, quality, latency, and authorised sellers.",example:"SIMULASI — dua jalur mengakses publisher yang sama: direct SSP dan beberapa reseller. Jalur reseller memiliki fee dan latency lebih tinggi tanpa added value. SPO analysis membantu memilih route yang lebih efisien.",actions:["Uraikan bid request → DSP evaluation → bid response → auction → ad serve.","Kenali field OpenRTB relevan seperti impression, site/app, device, user/context, and deal.","Audit seller chain, ads.txt, sellers.json, fee, duplication, and timeout."],practice:"Buat annotated OpenRTB bid request/response sederhana (synthetic JSON), supply-path diagram, and SPO comparison matrix. Jangan mengirim bid sungguhan.",qaFocus:["menjelaskan urutan RTB dan informasi dalam bid request","mengidentifikasi data fields yang sensitif atau tidak tersedia","menilai SPO dengan transparency, fees, duplication, dan quality"],terms:[["RTB","Real-time bidding."],["Supply Path Optimization","Evaluasi jalur supply untuk transparency dan efficiency."],["sellers.json","File untuk mengidentifikasi entitas yang menjual inventory melalui supply chain."]]},
  {concept:"Audience/data strategy menilai sumber first-party, contextual, and permitted partner signals. Identity solutions tidak selalu mengidentifikasi individu secara deterministik; coverage berbeda menurut browser, environment, and consent. Privacy and signal loss harus menjadi bagian desain campaign, bukan sekadar catatan setelah targeting.",example:"SIMULASI — target customer CRM memiliki consent untuk channel tertentu tetapi belum tentu untuk third-party audience activation. Specialist memisahkan eligible first-party use, contextual targeting, and non-eligible data.",actions:["Klasifikasikan source: advertiser first-party, platform, contextual, partner, or modeled.","Periksa provenance, consent, purpose limitation, retention, and activation permission.","Buat audience coverage/overlap hypothesis dan privacy risk log."],practice:"Rancang data and audience strategy: data source, purpose, consent, identity limitation, segment, match/coverage assumption, activation path, suppression, and measurement.",qaFocus:["membedakan first-party, contextual, partner, and inferred signals","membuktikan dasar penggunaan data sesuai consent/purpose","menjelaskan signal loss dan identity coverage limits"],terms:[["First-party data","Data yang dikumpulkan langsung oleh organisasi dari interaksinya."],["Contextual targeting","Penargetan berdasarkan konteks konten/placement."],["Identity graph","Sistem yang menghubungkan identifier; kualitas dan coverage bergantung data/consent."]]},
  {concept:"Inventory mencakup display, video, CTV, audio, DOOH, native, and in-app. Deal types menentukan harga, akses, auction, delivery commitment, and operational rights. Open auction biasanya terbuka; PMP/preferred gives negotiated access; Programmatic Guaranteed reserves delivery under agreed terms. Evaluate inventory and format according to audience, viewability, brand safety, and objective.",example:"SIMULASI — brand ingin reach premium audience melalui CTV dan video online. PMP dapat meningkatkan inventory control tetapi minimum commitment dan CPM lebih tinggi. Planner membandingkan open auction vs PMP vs PG.",actions:["Build inventory taxonomy by screen, format, environment, and publisher.","Compare deal type, floor/rate, commitment, delivery, targeting, and cancellation terms.","Match format and environment to objective and creative assets."],practice:"Buat inventory/deal matrix mencakup display, video, CTV, audio, DOOH; bandingkan open auction, PMP, preferred, and PG pada cost, control, commitment, risk, and use case.",qaFocus:["membedakan open auction, PMP, preferred, dan PG","memilih format berdasarkan audience dan tujuan","membaca komitmen delivery dan deal terms"],terms:[["Open auction","Auction inventory yang dapat diakses buyer eligible."],["Preferred deal","Kesepakatan harga/akses yang tidak selalu menjamin volume."],["Programmatic Guaranteed","Deal dengan harga dan delivery commitment yang disepakati."]]},
  {concept:"DSP architecture mengorganisasi advertiser, campaign, IO, line item, audience, inventory, creative, bid, budget, frequency, and reporting. DV360 menjadi platform latihan utama; TTD dan Amazon DSP dapat dibandingkan sebagai contoh environment lain. Menu, product naming, and access vary by contract and market; screenshot latihan harus berasal dari demo/account yang memang boleh diakses.",example:"SIMULASI — satu advertiser memiliki campaign awareness dan retargeting dengan budget, audience, and KPI berbeda. Struktur line item harus menjaga kontrol tanpa memecah data secara berlebihan.",actions:["Map advertiser/campaign/IO/line item/creative/audience relationships.","Identify required settings, permissions, pixels, and reporting levels.","Compare DV360/TTD/Amazon DSP concepts without assuming UI or access is identical."],practice:"Buat annotated DSP blueprint untuk DV360: advertiser, campaign, IO, line item, targeting, bidding, creative, tracking, and report. Jika tidak punya account access, gunakan workflow mockup dan labeli draft/demo.",qaFocus:["memahami hierarchy pada DSP","menentukan unit struktur sesuai budget/objective/targeting","membedakan platform UI screenshot asli dengan conceptual mockup"],terms:[["IO","Insertion Order pada platform buying."],["Line item","Unit konfigurasi delivery, targeting, bid, and budget."],["DSP seat","Akun/akses buyer yang mengelola media buying di DSP."]]},
  {concept:"Campaign structure dan trafficking menyiapkan flight, audience, inventory, creative, landing URL, macro, tracking, and naming. Creative format must meet publisher requirements, file size, duration, click destination, SSL, and fallback. Before launch, verify every placement/line item is mapped correctly; otherwise ad can serve wrong creative or lose measurement.",example:"SIMULASI — 300×250 display creative is uploaded to a video placement; URL macros are missing; tags fire but click reporting is incorrect. A trafficking sheet and preflight prevent these operational failures.",actions:["Build campaign structure and naming taxonomy.","Map creative specs, placement, URL/macro, tracker, and landing page.","Review QA evidence and publisher acceptance before launch."],practice:"Buat programmatic trafficking sheet dengan IO/line item, dates, audience, inventory, bid, budget, creative dimensions/file, URLs/macros, trackers, owner, QA status, and approval.",qaFocus:["memvalidasi asset/spec dan placement mapping","menjaga macro dan tracking parameter","menyimpan prelaunch QA dan approval"],terms:[["Trafficking","Proses konfigurasi campaign/ads/tags untuk delivery."],["Macro","Token dinamis yang diisi sistem pada URL/tag."],["Fallback creative","Aset cadangan jika format utama gagal dirender."]]},
  {concept:"Bidding, budget pacing, and frequency management harus dikelola bersama. CPM bid, optimization goal, inventory, competition, conversion signal, and pacing mode memengaruhi delivery. Frequency capping membatasi overexposure, tetapi harus dilihat lintas placement/deal where possible. Sudden changes can reset learning or alter auction behavior.",example:"SIMULASI — campaign underspends by 30% despite high bid. Diagnosis checks audience size, deal inventory, floor, targeting, creative rejection, pacing, and budget. Raising bid without identifying bottleneck may waste spend.",actions:["Select bid strategy based on objective, available event signal, and volume.","Set daily/lifetime budget, pacing mode, floor/bid guardrails, and frequency caps.","Review spend, impressions, win rate, CPA, quality, and saturation together."],practice:"Buat bidding & pacing plan: objective, bid method, CPM/CPA assumptions, budget pacing, frequency cap, audience saturation, underdelivery triggers, and optimization actions.",qaFocus:["membedakan bidding issue dengan inventory/targeting constraint","mengelola pacing dan frequency bersama","menghubungkan bid decision dengan objective dan event signal"],terms:[["Pacing","Kecepatan konsumsi budget terhadap jadwal."],["Win rate","Proporsi bid yang menang dari eligible bid."],["Frequency cap","Batas jumlah exposure per user/periode."]]},
  {concept:"Private Marketplace, preferred deals, and Programmatic Guaranteed differ in access, priority, price, and delivery commitment. Deal ID, buyer eligibility, floor, audience, inventory, creative acceptance, timeout, and publisher rules must be aligned. Deal negotiation also requires operational readiness; a deal without proper mapping may not deliver despite an agreed price.",example:"SIMULASI — buyer receives a PMP Deal ID with a floor price and strict dates, but the wrong seat is authorized and campaign does not bid. Deal-ID hygiene and test impressions are required.",actions:["Compare deal types on price, exclusivity, priority, commitment, and risk.","Verify Deal ID, buyer seat, publisher/supply partner, floor, targeting, and dates.","Track negotiated terms, test delivery, underdelivery, and makegoods."],practice:"Buat deal proposal one-pager comparing PMP, preferred, and PG. Include terms, Deal ID validation, inventory, minimums, floor, commitment, creative QA, and fallback plan.",qaFocus:["memilih deal type sesuai control/delivery need","memvalidasi Deal ID, seat, floor, and dates","memastikan deal contract terms tercermin di campaign setup"],terms:[["Deal ID","Identifier untuk mengakses inventory melalui deal."],["Floor price","Harga minimum yang disyaratkan seller."],["Priority","Urutan/keutamaan delivery pada inventory/deal."]]},
  {concept:"Verification separates viewability, invalid traffic, brand safety, and brand suitability. MRC measurement standards define measurement principles; IAS and DoubleVerify provide commercial verification solutions. Supply quality also includes ads.txt, sellers.json, reseller chain, domain/app transparency, and exclusion controls. One metric never proves all quality dimensions.",example:"SIMULASI — CPM is low, but 18% of measured impressions are invalid and a significant share appears on unsuitable content. Campaign should be evaluated by valid eligible reach and risk, not cheap volume alone.",actions:["Define metric scope: measured/eligible impressions, viewability threshold, IVT type, and brand-suitability policy.","Review vendor coverage, exclusions, verification logs, and publisher/domain lists.","Audit authorised sellers and supply path; record exceptions."],practice:"Buat supply-quality audit report: inventory source, ads.txt/sellers.json, viewability, IVT, suitability, vendor methodology, coverage, exclusion, risk, and remediation.",qaFocus:["membedakan viewability, IVT, safety, dan suitability","membaca coverage/denominator pada verification report","menelusuri reseller chain dan authorized sellers"],terms:[["Viewability","Apakah impression memenuhi kriteria terlihat yang ditetapkan."],["IVT","Invalid traffic."],["Brand suitability","Kesesuaian lingkungan konten untuk nilai/risiko brand."]]},
  {concept:"CM360 and Floodlight connect ad serving and conversion measurement across campaigns. Understand advertiser/campaign/site/placement/ad/creative structure, tag types, Floodlight activities, counting methods, conversion windows, and attribution. DSP and CM360 report differences may come from event definitions, timezone, deduplication, attribution, latency, and tracking setup.",example:"SIMULASI — DSP reports 800 conversions, CM360 reports 720, and GA4 reports 650 sessions with purchase. The discrepancy is investigated through conversion definitions, windows, identity, and deduplication rather than declared as error.",actions:["Map DSP, CM360 placement/ad/creative, Floodlight activity, and event flow.","Verify tag implementation, click/impression trackers, event_id, consent, and conversion counting.","Reconcile reporting source, timezone, windows, latency, and billable definitions."],practice:"Buat CM360 measurement plan: campaign/placement/creative map, Floodlight activity, tags, conversion window, counting method, test cases, discrepancy rules, and source-of-truth policy.",qaFocus:["memahami relasi placement/ad/creative dan Floodlight","menentukan conversion counting sesuai kebutuhan","menginvestigasi discrepancy dengan definisi sepadan"],terms:[["Floodlight activity","Aktivitas konversi yang diukur dalam Campaign Manager 360."],["Counting method","Aturan berapa kali conversion dihitung."],["Deduplication","Proses menghindari event/conversion yang terhitung ganda."]]},
  {concept:"Optimization harus melihat spend, win rate, inventory quality, audience, creative, viewability, IVT, frequency, conversion signal, and marginal return. Reporting menjelaskan apakah campaign delivery sesuai plan, bagaimana kualitas supply, and what should change. Post-campaign supply review is distinct from generic ROAS reporting.",example:"SIMULASI — a line item has low CTR but high qualified conversion rate on premium context. Pausing solely on CTR may harm outcomes; segment by objective, audience, format, and contribution.",actions:["Check daily pacing and campaign health by line item and deal.","Diagnose audience/creative/inventory/auction/tracking before changing bid.","Compare cost, valid reach, conversion quality, and post-buy evidence."],practice:"Buat weekly optimization report and post-campaign supply review from synthetic data: issue, evidence, change, owner, guardrail, result, and next action.",qaFocus:["mengoptimalkan berdasarkan tujuan, bukan satu metrik","memisahkan supply/auction/creative/tracking diagnosis","mengukur kualitas inventory selain volume"],terms:[["Post-campaign analysis","Evaluasi setelah campaign selesai."],["Supply quality","Kualitas dan transparansi inventory sumber."],["Marginal performance","Perubahan outcome dari tambahan/pengurangan investasi."]]},
  {concept:"Capstone Programmatic menyatukan strategy, audience/data, inventory, deal selection, DSP setup, creative/trafficking, bidding, verification, measurement, discrepancy, and post-buy. Buat audit trail dari brief sampai final invoice/report. Semua hasil sintetis harus ditandai; jangan mengklaim akses ke DSP production bila hanya mockup.",example:"SIMULASI — brand automotive ingin reach in-market audience melalui online video/CTV dan retargeting dengan budget Rp250 juta. Peserta memilih inventory/deal, menyiapkan DSP blueprint, pacing, quality verification, and post-campaign review.",actions:["Frame objective and audience; choose supply and deal model.","Design DSP structure, bidding, creatives, tracking, and QA.","Monitor quality, reconcile performance, and present optimization decisions."],practice:"Buat capstone pack: DSP blueprint, inventory/deal matrix, supply-path audit, trafficking sheet, bid/pacing plan, verification settings, measurement map, discrepancy report, and executive review.",qaFocus:["menjaga konsistensi dari deal sampai serving and measurement","membuktikan quality control dan reconciliation","menjelaskan trade-off inventory, price, delivery, and outcomes"],terms:[["SPO","Supply Path Optimization."],["Programmatic guaranteed","Deal dengan delivery commitment."],["Capstone pack","Kumpulan bukti kerja yang memperlihatkan workflow end-to-end."]]}
 ]
};
